module Uart_txd(
	sys_clk,
	rst_n,
	uart_en,
	data_send,
	send_busy,
	uart_txd);

	//---Ports declearation: generated by Robei---
	input sys_clk;
	input rst_n;
	input uart_en;
	input [7:0] data_send;
	output send_busy;
	output uart_txd;

	wire sys_clk;
	wire rst_n;
	wire uart_en;
	wire [7:0] data_send;
	reg send_busy;
	reg uart_txd;

	//----Code starts here: integrated by Robei-----
		 parameter F_SYS_CLK=33_333_333;//33_333_333
		 parameter BAUD_RATE=115200;
		
		 parameter IDLE=3'd0,
		                    START=3'd1,
		                    SEND_DATA=3'd2,
		                    STOP=3'd3;            
		 parameter CNT_BAUD=2;//正常应为F_SYS_CLK/BAUD_RATE，为便于仿真，设置为2
		    
		    reg [7:0]   data_reg;
		    reg [3:0]   cnt_data;
		    reg            txd_en;
		    reg [24:0] cnt_sys_clk;
		    reg [2:0]   state;
		    reg [2:0]   next_state;
		    
		    
		    //txd_en   
		    always@(posedge sys_clk or negedge rst_n)begin
		        if(!rst_n)
		            txd_en<=1'b0;
		        else if(state==START)
		            txd_en<=1'b1;
		        else if(state==IDLE)
		            txd_en<=1'b0; 
		        else
		            txd_en<=txd_en;
		    end
		    
		    //cnt_sys_clk
		    always@ (posedge sys_clk or negedge rst_n)begin
		        if(!rst_n)
		            cnt_sys_clk<=25'b0;
		        else if(txd_en)
		            if(cnt_sys_clk==CNT_BAUD-1)
		                cnt_sys_clk<=25'b0;
		            else
		                cnt_sys_clk<=cnt_sys_clk+1;
		        else
		             cnt_sys_clk<=25'b0;
		    end
		  
		  // state
		  always @(posedge sys_clk or negedge rst_n)begin
		      if(!rst_n)
		          state<=3'b000;
		      else
		          state<=next_state;
		  end 
		  
		  always@(*)begin
		      if(!rst_n)
		          next_state=3'b000;
		      else 
		          case(state)
		              IDLE:begin
		                  if(uart_en) 
		                      next_state= START;
		                  else
		                      next_state= IDLE;
		              end
		              START:begin
		                  if(cnt_sys_clk==CNT_BAUD-2)
		                      next_state= SEND_DATA;
		                  else
		                      next_state= START;
		              end
		              SEND_DATA:begin
		                  if(cnt_data==4'd8)
		                      next_state= STOP;
		                  else
		                     next_state= SEND_DATA;
		              end
		              STOP:begin
		                  if(cnt_sys_clk==CNT_BAUD-2)
		                      next_state=IDLE;
		                  else
		                      next_state= STOP;
		              end
		              default: ;
		          endcase                                                                           
		  end 
		  
		  //
		  always @(posedge sys_clk or negedge rst_n)begin
		      if(!rst_n)begin
		          send_busy<=1'b0;
		          uart_txd<=1'b1;
		          data_reg<=8'b0000_0000; 
		          cnt_data<=4'b0000; 
		      end      
		      else
		          case(state)
		              IDLE:begin
		                   send_busy<=1'b0;
		                   uart_txd<=1'b1;
		                   data_reg<=8'b0000_0000;
		                   cnt_data<=4'b0000; 
		              end
		              START:begin
		                  send_busy<=1'b1;
		                  uart_txd<=1'b0;
		                  data_reg<=data_send;
		              end
		              SEND_DATA:begin
		                  if(cnt_data<4'd8)
		                      uart_txd<=data_reg[cnt_data];
		                  else
		                      uart_txd<=uart_txd;
		                  if(cnt_sys_clk==CNT_BAUD-2)
		                      cnt_data<=cnt_data+1;
		                  else
		                      cnt_data<=cnt_data;                  
		              end
		              STOP:begin
		                  cnt_data<=4'b0000;
		                  uart_txd<=1'b1;
		              end
		              default: ;
		          endcase      
		  end
	
	
	
endmodule    //Uart_txd

